import type { AnchorHTMLAttributes, HTMLAttributes, LiHTMLAttributes, OlHTMLAttributes } from "react";

export function Breadcrumb({ className = "", ...props }: HTMLAttributes<HTMLElement>) { return <nav aria-label="Breadcrumb" className={className} {...props} />; }
export function BreadcrumbList({ className = "", ...props }: OlHTMLAttributes<HTMLOListElement>) { return <ol className={`co-flex co-flex-wrap co-items-center co-gap-2 co-text-sm co-text-black/60 ${className}`.trim()} {...props} />; }
export function BreadcrumbItem({ className = "", ...props }: LiHTMLAttributes<HTMLLIElement>) { return <li className={`co-inline-flex co-items-center co-gap-2 ${className}`.trim()} {...props} />; }
export function BreadcrumbLink({ className = "", ...props }: AnchorHTMLAttributes<HTMLAnchorElement>) { return <a className={`hover:co-text-black focus-visible:co-ring-2 ${className}`.trim()} {...props} />; }
export function BreadcrumbPage({ className = "", ...props }: HTMLAttributes<HTMLSpanElement>) { return <span aria-current="page" className={`co-font-medium co-text-black ${className}`.trim()} {...props} />; }
export function BreadcrumbSeparator({ className = "", children = "/", ...props }: LiHTMLAttributes<HTMLLIElement>) { return <li role="presentation" aria-hidden="true" className={className} {...props}>{children}</li>; }
